import React, { useState } from 'react';
import './landing.css';
import { db } from '../firebase-config'; // Importez votre configuration Firebase
import { collection, addDoc } from 'firebase/firestore'; // Firebase Firestore

const Landing = () => {
  const [investment, setInvestment] = useState(0);
  const [sales, setSales] = useState([{ name: '', purchasePrice: '', salePrice: '', quantity: '' }]);
  const [rentals, setRentals] = useState([{ name: '', rentalPrice: '', rentalCount: '' }]);
  const [expenses, setExpenses] = useState([{ name: '', amount: '' }]);
  const [salesProfit, setSalesProfit] = useState(0);
  const [rentalIncome, setRentalIncome] = useState(0);
  const [totalExpenses, setTotalExpenses] = useState(0);
  const [remainingInvestment, setRemainingInvestment] = useState(0);
  const [totalGains, setTotalGains] = useState(0);
  const [sadaqaPercentage, setSadaqaPercentage] = useState(0);
  const [sadaqaAmount, setSadaqaAmount] = useState(0);
  const [sadaqaStatus, setSadaqaStatus] = useState('Pas encore');
  const [sadaqaPaid, setSadaqaPaid] = useState(0); // Montant payé pour la Sadaqa

  const activitiesCollectionRef = collection(db, 'activities'); // Référence à la collection Firebase

  const handleAddSale = () => {
    setSales([...sales, { name: '', purchasePrice: '', salePrice: '', quantity: '' }]);
  };

  const handleAddRental = () => {
    setRentals([...rentals, { name: '', rentalPrice: '', rentalCount: '' }]);
  };

  const handleAddExpense = () => {
    setExpenses([...expenses, { name: '', amount: '' }]);
  };

  const calculateSalesProfit = () => {
    const profit = sales.reduce(
      (acc, sale) =>
        acc +
        ((parseFloat(sale.salePrice) - parseFloat(sale.purchasePrice)) * parseFloat(sale.quantity) || 0),
      0
    );
    setSalesProfit(profit);
  };

  const calculateRentalIncome = () => {
    const income = rentals.reduce(
      (acc, rental) => acc + (parseFloat(rental.rentalPrice) * parseFloat(rental.rentalCount) || 0),
      0
    );
    setRentalIncome(income);
  };

  const calculateTotalExpenses = () => {
    const expensesTotal = expenses.reduce(
      (acc, expense) => acc + (parseFloat(expense.amount) || 0),
      0
    );
    setTotalExpenses(expensesTotal);
  };

  const calculateRemainingInvestment = () => {
    const totalIncome = salesProfit + rentalIncome;
    const remaining = investment - totalIncome + totalExpenses;
    setRemainingInvestment(remaining);

    // Calculer les gains totaux
    const gains = totalIncome - totalExpenses;
    setTotalGains(gains);

    // Calculer la Sadaqa
    const sadaqa = (gains * sadaqaPercentage) / 100;
    setSadaqaAmount(sadaqa);
  };

  const saveActivityToFirebase = async () => {
    try {
      await addDoc(activitiesCollectionRef, {
        date: new Date().toISOString(),
        investment,
        sales,
        rentals,
        expenses,
        totalGains,
        sadaqaPercentage,
        sadaqaAmount,
        sadaqaStatus,
        sadaqaPaid,
      });
      alert('Activité sauvegardée avec succès dans Firebase !');
    } catch (error) {
      console.error('Erreur lors de la sauvegarde :', error);
    }
  };

  return (
    <div className="container mt-5">
      <h1 className="text-center">💰 Gestion de l'Argent 💰</h1>
      <p className="text-center">
        Calculez vos profits ou pertes en fonction de vos investissements, ventes, locations et dépenses.
      </p>

      {/* Section Investissement */}
      <div className="mt-4 section">
        <h3>💵 Investissement</h3>
        <div className="form-group">
          <label>Montant total investi :</label>
          <input
            type="text"
            className="form-control"
            value={investment}
            onChange={(e) => setInvestment(e.target.value)}
            placeholder="Exemple : 10000 DH"
          />
        </div>
      </div>

      {/* Section Ventes */}
      <div className="mt-4 section">
        <h3>🛒 Ventes</h3>
        {sales.map((sale, index) => (
          <div key={index} className="mb-3">
            <input
              type="text"
              className="form-control mb-2"
              value={sale.name}
              onChange={(e) => {
                const newSales = [...sales];
                newSales[index].name = e.target.value;
                setSales(newSales);
              }}
              placeholder="Nom de l'article (ex : biscuit, eau)"
            />
            <input
              type="text"
              className="form-control mb-2"
              value={sale.purchasePrice}
              onChange={(e) => {
                const newSales = [...sales];
                newSales[index].purchasePrice = e.target.value;
                setSales(newSales);
              }}
              placeholder="Prix d'achat (ex : 1.50 DH)"
            />
            <input
              type="text"
              className="form-control mb-2"
              value={sale.salePrice}
              onChange={(e) => {
                const newSales = [...sales];
                newSales[index].salePrice = e.target.value;
                setSales(newSales);
              }}
              placeholder="Prix de vente (ex : 2.00 DH)"
            />
            <input
              type="text"
              className="form-control"
              value={sale.quantity}
              onChange={(e) => {
                const newSales = [...sales];
                newSales[index].quantity = e.target.value;
                setSales(newSales);
              }}
              placeholder="Nombre de ventes (ex : 10)"
            />
          </div>
        ))}
        <button className="btn btn-secondary" onClick={handleAddSale}>
          ➕ Ajouter une vente
        </button>
        <button className="btn btn-primary mt-2" onClick={calculateSalesProfit}>
          🧮 Calculer le profit des ventes
        </button>
        <p className="mt-2">Profit des ventes : {salesProfit} DH</p>
      </div>

      {/* Section Locations */}
      <div className="mt-4 section">
        <h3>🎲 Locations</h3>
        {rentals.map((rental, index) => (
          <div key={index} className="mb-3">
            <input
              type="text"
              className="form-control mb-2"
              value={rental.name}
              onChange={(e) => {
                const newRentals = [...rentals];
                newRentals[index].name = e.target.value;
                setRentals(newRentals);
              }}
              placeholder="Nom du jouet (ex : ballon, vélo)"
            />
            <input
              type="text"
              className="form-control mb-2"
              value={rental.rentalPrice}
              onChange={(e) => {
                const newRentals = [...rentals];
                newRentals[index].rentalPrice = e.target.value;
                setRentals(newRentals);
              }}
              placeholder="Prix de location (ex : 5 €)"
            />
            <input
              type="text"
              className="form-control"
              value={rental.rentalCount}
              onChange={(e) => {
                const newRentals = [...rentals];
                newRentals[index].rentalCount = e.target.value;
                setRentals(newRentals);
              }}
              placeholder="Nombre de locations (ex : 3)"
            />
          </div>
        ))}
        <button className="btn btn-secondary" onClick={handleAddRental}>
          ➕ Ajouter une location
        </button>
        <button className="btn btn-primary mt-2" onClick={calculateRentalIncome}>
          🧮 Calculer les revenus des locations
        </button>
        <p className="mt-2">Revenus des locations : {rentalIncome} €</p>
      </div>

      {/* Section Dépenses */}
      <div className="mt-4 section">
        <h3>🍔 Dépenses</h3>
        {expenses.map((expense, index) => (
          <div key={index} className="mb-3">
            <input
              type="text"
              className="form-control mb-2"
              value={expense.name}
              onChange={(e) => {
                const newExpenses = [...expenses];
                newExpenses[index].name = e.target.value;
                setExpenses(newExpenses);
              }}
              placeholder="Nom de la dépense (ex : sandwich, café)"
            />
            <input
              type="text"
              className="form-control"
              value={expense.amount}
              onChange={(e) => {
                const newExpenses = [...expenses];
                newExpenses[index].amount = e.target.value;
                setExpenses(newExpenses);
              }}
              placeholder="Montant de la dépense (ex : 3.50 €)"
            />
          </div>
        ))}
        <button className="btn btn-secondary" onClick={handleAddExpense}>
          ➕ Ajouter une dépense
        </button>
        <button className="btn btn-primary mt-2" onClick={calculateTotalExpenses}>
          🧮 Calculer les dépenses totales
        </button>
        <p className="mt-2">Dépenses totales : {totalExpenses} €</p>
      </div>

      {/* Section Sadaqa */}
      <div className="mt-4 section">
        <h3>🤲 Sadaqa</h3>
        <div className="form-group">
          <label>Pourcentage de Sadaqa :</label>
          <input
            type="number"
            className="form-control"
            value={sadaqaPercentage}
            onChange={(e) => setSadaqaPercentage(e.target.value)}
            placeholder="Exemple : 2%"
          />
        </div>
        <div className="form-group">
          <label>Statut de la Sadaqa :</label>
          <select
            className="form-control"
            value={sadaqaStatus}
            onChange={(e) => setSadaqaStatus(e.target.value)}
          >
            <option value="Pas encore">Pas encore</option>
            <option value="Donné">Donné</option>
            <option value="Partiellement payé">Partiellement payé</option>
          </select>
        </div>
        {sadaqaStatus === 'Partiellement payé' && (
          <div className="form-group">
            <label>Montant payé :</label>
            <input
              type="number"
              className="form-control"
              value={sadaqaPaid}
              onChange={(e) => setSadaqaPaid(e.target.value)}
              placeholder="Exemple : 50 DH"
            />
          </div>
        )}
        <p>Montant total de la Sadaqa : {sadaqaAmount.toFixed(2)} DH</p>
        {sadaqaStatus === 'Partiellement payé' && (
          <p>Montant restant : {(sadaqaAmount - sadaqaPaid).toFixed(2)} DH</p>
        )}
      </div>

      {/* Résumé et sauvegarde */}
      <div className="mt-4 section">
        <h3>📊 Résumé</h3>
        <button className="btn btn-success" onClick={calculateRemainingInvestment}>
          🧮 Calculer le reste de l'investissement
        </button>
        <button className="btn btn-primary ml-2" onClick={saveActivityToFirebase}>
          💾 Sauvegarder dans Firebase
        </button>
        <p className="mt-2">
          📅 Aujourd'hui, vous avez gagné un total de <strong>{totalGains} DH</strong>.
        </p>
        <p>Il vous reste {remainingInvestment} DH pour couvrir votre investissement.</p>
        <p>
          Statut de la Sadaqa : <strong>{sadaqaStatus}</strong>
        </p>
        <p>
          Montant total de la Sadaqa : <strong>{sadaqaAmount.toFixed(2)} DH</strong>
        </p>
        {sadaqaStatus === 'Partiellement payé' && (
          <p>
            Montant payé : <strong>{sadaqaPaid} DH</strong>, Montant restant :{' '}
            <strong>{(sadaqaAmount - sadaqaPaid).toFixed(2)} DH</strong>
          </p>
        )}
      </div>
    </div>
  );
};

export default Landing;
